import{_ as i,o,c as t,a3 as e}from"./chunks/framework.D8u9WiMi.js";const h=JSON.parse('{"title":"十六号的流水账","description":"","frontmatter":{},"headers":[],"relativePath":"listOfEvents/2026/march/16.md","filePath":"listOfEvents/2026/march/16.md"}'),a={name:"listOfEvents/2026/march/16.md"};function p(s,l,r,n,_,d){return o(),t("div",null,[...l[0]||(l[0]=[e('<h1 id="十六号的流水账" tabindex="-1">十六号的流水账 <a class="header-anchor" href="#十六号的流水账" aria-label="Permalink to &quot;十六号的流水账&quot;">​</a></h1><ol><li><p>List集合</p><ol><li>存取有序</li><li>可以重复</li><li>有索引</li></ol></li><li><p>ArrayList集合</p></li><li><p>LinkedList集合</p><ol><li>双向链表实现类，可以用来存储一组有序的元素。</li><li>所有的node都包含了指向当前，前一个，后一个元素的指针</li></ol></li><li><p>Set集合</p><ol><li>无序</li><li>不重复</li><li>无索引</li></ol></li><li><p>HashSet集合</p><ol><li>根据hashCode方法算出来的int类型的整数</li></ol></li><li><p>LinkedHashSet集合</p><ol><li>有序</li><li>不重复</li><li>无索引</li></ol></li><li><p>Set 不能重复，无索引的集合</p></li><li><p>Map key不能重复，无索引的键值对对象的集合</p></li><li><p>如果想要集合中的元素可重复</p><ol><li>用ArrayList集合，基于数组的（用的最多）</li></ol></li><li><p>如果想要集合中的元素可重复，而且当前的<strong>增删操作明显多余查询</strong></p><ol><li>用LinkedList集合，基于链表的</li></ol></li><li><p>如果想对集合中的元素去重</p><ol><li>用hashset集合，哈希表的，（用的最多）</li></ol></li><li><p>如果想对集合中的元素去重，而且保证存取顺序</p><ol><li>用LinkedHashSet集合，基于哈希表和双链表，效率低于HashSet</li></ol></li><li><p>如果想对集合中的元素进行排序</p><ol><li>用TreeSet集合，，基于红黑树，后续也可以用List集合实现排序</li></ol></li><li><p>map 存储键值对</p><ol><li>不能取单项</li><li>在添加数据时，如果key存在则替换，，否则直接添加</li><li>遍历方式：键找值</li></ol></li></ol><p>java课程小项目</p><ol><li>打开登录面板</li><li>选择登录，注册，退出 <ol><li>注册，输入用户名 <ol><li>用户名有长度3-8，格式只能是字母和数字组成</li><li>用户名不能重复</li></ol></li><li>输入两次密码</li><li>判断是否相同 <ol><li>也有长度限制3-8，必须是字母和数字共同组成</li><li>然后将用户名和密码创建的user加到list中</li></ol></li></ol></li></ol><p>弄了个简单的第一篇公众号说明稿</p>',5)])])}const m=i(a,[["render",p]]);export{h as __pageData,m as default};
